                self.emit_operation_failure_check()?;
                self.line(&format!("{source_flag} = false;"));
                for line in plan.apply_at(&expr.id)?.lines() {
                    self.line(line);
                }
                Ok(CValue {
                    code: plan.result_at(&expr.id).unwrap_or(&destination).to_owned(),
                    ty: return_type,
