//! Reachability-gated C11 runtime for the internal Owned Bounded Vec v1 lane.

mod copy_record;
pub(super) mod owned_leaf;
mod owned_payload;
mod sort;

pub(super) fn emit_runtime(
    output: &mut impl super::COutput,
    program: &crate::hir::ResolvedProgram,
) {
    let sort_keys = crate::vec_ops::sort_keys::uses(program);
    if sort_keys {
        output.push_str(include_str!("native_vec/sort_keys_check.c"));
    }
    let owned_leaf = program_uses_owned_leaf(program);
    if owned_leaf
        || crate::vec_ops::resolved_program_uses_owned_payload(program)
        || crate::hir::owned_record_collection::program_uses_profile(program)
    {
        owned_payload::emit_runtime_for_owned_leaf(output, owned_leaf);
        if owned_leaf {
            owned_leaf::emit_runtime(output, program);
        }
        if crate::vec_ops::resolved_program_uses_sort(program) {
            sort::emit_runtime(output);
        }
        if crate::hir::copy_record_collection::program_uses(program) {
            copy_record::emit_runtime(output, sort_keys);
        }
        emit_field_unique_runtime(output, program, owned_leaf);
        return;
    }
    output.push_str(NATIVE_VEC_RUNTIME_C);
    output.push_str(NATIVE_VEC_RUNTIME_SUFFIX_C);
    if crate::vec_ops::resolved_program_uses_sort(program) {
        sort::emit_runtime(output);
    }
    if program_uses_extended_ops(program) {
        output.push_str(NATIVE_VEC_EXTENDED_RUNTIME_C);
    }
    if crate::hir::copy_record_collection::program_uses(program) {
        copy_record::emit_runtime(output, sort_keys);
    }
    emit_field_unique_runtime(output, program, false);
}

/// Borrowed Record-Field Uniqueness v1 helpers follow their family runtimes;
/// programs without the operation keep their exact prior runtime text.
fn emit_field_unique_runtime(
    output: &mut impl super::COutput,
    program: &crate::hir::ResolvedProgram,
    owned_leaf: bool,
) {
    if !crate::vec_ops::field_unique::uses(program) {
        return;
    }
    output.push_str(include_str!("native_vec/field_unique.c"));
    if crate::hir::copy_record_collection::program_uses(program) {
        output.push_str(include_str!("native_vec/copy_field_unique.c"));
    }
    if owned_leaf {
        output.push_str(include_str!("native_vec/owned_field_unique.c"));
    }
}

/// New carriers or additive operations select this runtime; frozen legacy
/// constructors and signatures alone preserve the original emitted bytes.
pub(super) fn program_uses_owned_leaf(program: &crate::hir::ResolvedProgram) -> bool {
    use crate::hir::ResolvedType;
    let new_element = |element: &ResolvedType| {
        crate::hir::owned_leaf_collection::layout(&program.declarations, element).is_some()
            && !crate::hir::owned_record_collection::is_admitted_owned_record_collection_element(
                &program.declarations,
                element,
            )
    };
    let new_carrier = |ty: &ResolvedType| {
        crate::hir::collection_outcome::owned_admitted(&program.declarations, ty)
            || matches!(ty, ResolvedType::Nominal { declaration, arguments }
        if matches!(declaration.as_str(), crate::prelude::VEC_ID
            | crate::iterator_ops::ITER_ID | crate::iterator_ops::STEP_ID)
        && matches!(arguments.as_slice(), [element] if new_element(element)))
    };
    crate::hir::collection_outcome::nested::program_requires_profile(program)
        || crate::hir::owned_collection_record::program_requires_profile(program)
        || program
            .functions
            .iter()
            .chain(program.function_instances.iter().map(|i| &i.function))
            .any(|f| {
                if new_carrier(&f.return_type) || f.params.iter().any(|p| new_carrier(&p.ty)) {
                    return true;
                }
                std::iter::once(&f.body)
                    .chain(f.requires.iter())
                    .chain(f.ensures.iter())
                    .any(|root| {
                        let mut pending = vec![root];
                        while let Some(expression) = pending.pop() {
                            if matches!(
                                expression.kind,
                                crate::hir::ResolvedExprKind::VecFieldRead { .. }
                            ) || new_carrier(&expression.ty)
                            {
                                return true;
                            }
                            crate::hir::push_resolved_expression_children_in_authored_order(
                                expression,
                                &mut pending,
                            );
                        }
                        let mut found = false;
                        crate::hir::visit_resolved_calls(
                            root,
                            &mut |callee, instance, arguments| {
                                if instance.is_none() {
                                    if let (Some(op), [element]) =
                                        (crate::vec_ops::by_id(callee.as_str()), arguments)
                                    {
                                        found |= new_element(element)
                                            || matches!(
                                                op,
                                                crate::vec_ops::VecOp::CloneAt
                                                    | crate::vec_ops::VecOp::UpdateField
                                                    | crate::vec_ops::VecOp::Replace
                                                    | crate::vec_ops::VecOp::ReserveOwned
                                                    | crate::vec_ops::VecOp::SortOwned
                                            )
                                            || (matches!(
                                                op,
                                                crate::vec_ops::VecOp::SortBy
                                                    | crate::vec_ops::VecOp::UniqueBy
                                            ) && crate::hir::owned_leaf_collection::layout(
                                                &program.declarations,
                                                element,
                                            )
                                            .is_some());
                                    }
                                }
                            },
                        );
                        found
                    })
            })
}

pub(super) fn program_uses_vec(program: &crate::hir::ResolvedProgram) -> bool {
    program_uses_owned_leaf(program)
        || crate::hir::copy_record_collection::program_uses(program)
        || program
            .functions
            .iter()
            .chain(
                program
                    .function_instances
                    .iter()
                    .map(|instance| &instance.function),
            )
            .any(|function| {
                crate::codegen::native_emit::is_native_owned_vec_type(
                    program,
                    &function.return_type,
                ) || function.params.iter().any(|param| {
                    crate::codegen::native_emit::is_native_owned_vec_type(program, &param.ty)
                }) || std::iter::once(&function.body)
                    .chain(function.requires.iter())
                    .chain(function.ensures.iter())
                    .any(|root| {
                        let mut found = false;
                        crate::hir::visit_resolved_calls(
                            root,
                            &mut |callee, instance, arguments| {
                                found |= instance.is_none()
                                    && arguments.len() == 1
                                    && crate::vec_ops::by_id(callee.as_str()).is_some();
                            },
                        );
                        found
                    })
            })
}

fn program_uses_extended_ops(program: &crate::hir::ResolvedProgram) -> bool {
    program
        .functions
        .iter()
        .chain(
            program
                .function_instances
                .iter()
                .map(|instance| &instance.function),
        )
        .any(|function| {
            let mut found = false;
            for expression in function
                .requires
                .iter()
                .chain(std::iter::once(&function.body))
                .chain(&function.ensures)
            {
                crate::hir::visit_resolved_calls(expression, &mut |callee, instance, _| {
                    found |= instance.is_none()
                        && matches!(
                            crate::vec_ops::by_id(callee.as_str()),
                            Some(
                                crate::vec_ops::VecOp::ReserveExact
                                    | crate::vec_ops::VecOp::Set
                                    | crate::vec_ops::VecOp::Clear
                            )
                        );
                });
            }
            found
        })
}

const NATIVE_VEC_RUNTIME_C: &str = r#"#include <stddef.h>
#include <stdlib.h>

#define SPX_VEC_MAX_CAPACITY UINT64_C(8192)

typedef struct {
    uint64_t *ptr;
    uint64_t len;
    uint64_t capacity;
    uint64_t generation;
    uint32_t type_tag;
    uint32_t authority;
} spx_vec_v1;

static __attribute__((unused)) uint64_t spx_vec_f32_bits(float value) {
    union { float value; uint32_t bits; } carrier = { .value = value };
    return (uint64_t)carrier.bits;
}
static __attribute__((unused)) uint64_t spx_vec_f64_bits(double value) {
    union { double value; uint64_t bits; } carrier = { .value = value };
    return carrier.bits;
}
static __attribute__((unused)) float spx_vec_bits_f32(uint64_t bits) {
    union { float value; uint32_t bits; } carrier = { .bits = (uint32_t)bits };
    return carrier.value;
}
static __attribute__((unused)) double spx_vec_bits_f64(uint64_t bits) {
    union { double value; uint64_t bits; } carrier = { .bits = bits };
    return carrier.value;
}

static __attribute__((unused)) struct spx_vec_authority_entry *spx_vec_require_valid(
    struct spx_context *spx_ctx, const spx_vec_v1 *value, uint32_t tag
) {
    if (spx_ctx == NULL || spx_ctx->state != SPX_CONTEXT_INITIALIZED || value == NULL
        || tag < UINT32_C(1) || tag > UINT32_C(8)
        || value->type_tag != tag || value->generation == UINT64_C(0)
        || value->authority == UINT32_C(0)
        || value->authority > SPX_VEC_AUTHORITY_CAPACITY
        || value->capacity > SPX_VEC_MAX_CAPACITY || value->len > value->capacity
        || ((value->capacity == UINT64_C(0)) != (value->ptr == NULL))) {
        spx_runtime_invariant_failure("invalid owned bounded Vec carrier");
    }
    struct spx_vec_authority_entry *entry =
        &spx_ctx->vec_authority[value->authority - UINT32_C(1)];
    if (!entry->live || entry->ptr != value->ptr || entry->len != value->len
        || entry->capacity != value->capacity || entry->generation != value->generation
        || entry->type_tag != value->type_tag) {
        spx_runtime_invariant_failure("stale or forged owned bounded Vec carrier");
    }
    return entry;
}

static __attribute__((unused)) uint64_t spx_vec_next_generation(struct spx_context *spx_ctx) {
    if (spx_ctx->vec_next_generation == UINT64_C(0)
        || spx_ctx->vec_next_generation == UINT64_MAX) {
        spx_runtime_invariant_failure("bounded Vec generation authority exhausted");
    }
    return spx_ctx->vec_next_generation++;
}

static __attribute__((unused)) uint32_t spx_vec_register(
    struct spx_context *spx_ctx, uint64_t *ptr, uint64_t capacity, uint32_t tag,
    uint64_t generation
) {
    for (uint32_t index = UINT32_C(0); index < SPX_VEC_AUTHORITY_CAPACITY; ++index) {
        struct spx_vec_authority_entry *entry = &spx_ctx->vec_authority[index];
        if (!entry->live) {
            entry->ptr = ptr; entry->len = UINT64_C(0); entry->capacity = capacity;
            entry->generation = generation; entry->type_tag = tag; entry->live = true;
            return index + UINT32_C(1);
        }
    }
    return UINT32_C(0);
}

static __attribute__((unused)) spx_status_token spx_vec_failure(
    struct spx_context *spx_ctx, uint32_t code
) {
    spx_status_token token = SPX_STATUS_SUCCESS;
    if (!spx_status_record_adapter(spx_ctx, "semaprax.vec.v1", code,
        SPX_STATUS_CLASS_ADAPTER, SPX_RETRYABILITY_FALSE, &token)) {
        spx_runtime_invariant_failure("bounded Vec status could not be recorded");
    }
    return token;
}

static __attribute__((unused)) spx_status_token spx_vec_with_capacity(
    struct spx_context *spx_ctx, uint32_t tag, uint64_t capacity, spx_vec_v1 *result
) {
    if (spx_ctx == NULL || spx_ctx->state != SPX_CONTEXT_INITIALIZED
        || result == NULL || tag < UINT32_C(1) || tag > UINT32_C(8)) {
        spx_runtime_invariant_failure("invalid bounded Vec allocation request");
    }
    *result = (spx_vec_v1){0};
    if (capacity > SPX_VEC_MAX_CAPACITY) return spx_vec_failure(spx_ctx, UINT32_C(3));
    uint64_t *payload = capacity == UINT64_C(0)
        ? NULL : (uint64_t *)calloc((size_t)capacity, sizeof(uint64_t));
    if (capacity != UINT64_C(0) && payload == NULL) return spx_vec_failure(spx_ctx, UINT32_C(3));
    uint64_t generation = spx_vec_next_generation(spx_ctx);
    uint32_t authority = spx_vec_register(spx_ctx, payload, capacity, tag, generation);
    if (authority == UINT32_C(0)) {
        free(payload); return spx_vec_failure(spx_ctx, UINT32_C(3));
    }
    result->ptr = payload; result->capacity = capacity; result->generation = generation;
    result->authority = authority; result->type_tag = tag;
    return SPX_STATUS_SUCCESS;
}

static __attribute__((unused)) spx_status_token spx_vec_push(
    struct spx_context *spx_ctx, uint32_t tag, spx_vec_v1 *source,
    uint64_t bits, spx_vec_v1 *result
) {
    struct spx_vec_authority_entry *entry = spx_vec_require_valid(spx_ctx, source, tag);
    if (result == NULL || result == source) spx_runtime_invariant_failure("invalid bounded Vec push result");
    if (source->len == source->capacity) return spx_vec_failure(spx_ctx, UINT32_C(1));
    source->ptr[source->len] = bits; source->len += UINT64_C(1);
    source->generation = spx_vec_next_generation(spx_ctx);
    entry->len = source->len; entry->generation = source->generation;
    result->ptr = source->ptr; result->len = source->len; result->capacity = source->capacity;
    result->generation = source->generation; result->authority = source->authority;
    result->type_tag = source->type_tag; *source = (spx_vec_v1){0};
    return SPX_STATUS_SUCCESS;
}

"#;

const NATIVE_VEC_EXTENDED_RUNTIME_C: &str = r#"#ifndef SPX_VEC_REALLOC
#define SPX_VEC_REALLOC realloc
#endif

static __attribute__((unused)) spx_status_token spx_vec_reserve_exact(
    struct spx_context *spx_ctx, uint32_t tag, spx_vec_v1 *source,
    uint64_t additional, spx_vec_v1 *result
) {
    struct spx_vec_authority_entry *entry = spx_vec_require_valid(spx_ctx, source, tag);
    if (result == NULL || result == source) spx_runtime_invariant_failure("invalid bounded Vec reserve result");
    if (additional > UINT64_MAX - source->len) return spx_vec_failure(spx_ctx, UINT32_C(3));
    uint64_t required = source->len + additional;
    uint64_t target = source->capacity > required ? source->capacity : required;
    if (target > SPX_VEC_MAX_CAPACITY) return spx_vec_failure(spx_ctx, UINT32_C(3));
    uint64_t *payload = source->ptr;
    if (target != source->capacity) {
        payload = (uint64_t *)SPX_VEC_REALLOC(source->ptr, (size_t)target * sizeof(uint64_t));
        if (payload == NULL) return spx_vec_failure(spx_ctx, UINT32_C(3));
    }
    source->ptr = payload; source->capacity = target;
    source->generation = spx_vec_next_generation(spx_ctx);
    entry->ptr = payload; entry->capacity = target; entry->generation = source->generation;
    result->ptr = source->ptr; result->len = source->len; result->capacity = source->capacity;
    result->generation = source->generation; result->authority = source->authority;
    result->type_tag = source->type_tag; *source = (spx_vec_v1){0};
    return SPX_STATUS_SUCCESS;
}

static __attribute__((unused)) spx_status_token spx_vec_set(
    struct spx_context *spx_ctx, uint32_t tag, spx_vec_v1 *source,
    uint64_t index, uint64_t bits, spx_vec_v1 *result
) {
    struct spx_vec_authority_entry *entry = spx_vec_require_valid(spx_ctx, source, tag);
    if (result == NULL || result == source) spx_runtime_invariant_failure("invalid bounded Vec set result");
    if (index >= source->len) return spx_vec_failure(spx_ctx, UINT32_C(2));
