type RangeBindings = Vec<(ExpressionId, RangeBinding)>;

fn build_range_bindings(
    program: &ResolvedProgram,
    executable_functions: &[(&ResolvedFunction, FunctionExecutionId)],
    variant_layouts: &VariantLayoutCache,
    first_global: u32,
