//! Scoped read of one authenticated field; no owning argument epoch or result.
use crate::hir;

use super::*;

pub(super) fn uses(program: &ResolvedProgram) -> bool {
    // Row Loan v1 helpers read lent rows through the same private import.
    if crate::vec_ops::string_slot::resolved_uses(program)
        || crate::hir::row_loan::program_uses(program)
    {
        return true;
    }
    program
        .functions
        .iter()
        .chain(program.function_instances.iter().map(|i| &i.function))
        .any(|function| {
            std::iter::once(&function.body)
                .chain(&function.requires)
                .chain(&function.ensures)
                .any(crate::vec_field::expression_uses)
        })
}

/// Only additive read programs construct legacy storage with its descriptor
/// already installed. Their existing tag-10 push/length/drop routes stay exact.
pub(super) fn typed_legacy_constructor(
    program: &ResolvedProgram,
    op: crate::vec_ops::VecOp,
) -> bool {
    op == crate::vec_ops::VecOp::WithCapacity && uses(program)
}

