//! OPT-723 private Core-Wasm host qualification for directly owned leaves.
#[path = "owned_leaf_vec/consuming_renewal.rs"]
mod consuming_renewal;
#[path = "owned_leaf_vec/contract_owners.rs"]
mod contract_owners;
#[path = "owned_leaf_vec/field_reads.rs"]
mod field_reads;
#[path = "owned_leaf_vec/copy_field_update.rs"]
mod copy_field_update;
#[path = "owned_leaf_vec/field_unique.rs"]
mod field_unique;
#[path = "owned_leaf_vec/if_handoff.rs"]
mod if_handoff;
#[path = "owned_leaf_vec/loop_renewal.rs"]
mod loop_renewal;
#[path = "owned_leaf_vec/record_traversal.rs"]
mod record_traversal;
#[path = "owned_leaf_vec/sort_keys.rs"]
mod sort_keys;
#[path = "owned_leaf_vec/string_slots.rs"]
mod string_slots;
#[path = "owned_leaf_vec/vec_constructor.rs"]
mod vec_constructor;

use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

static SEQUENCE: AtomicU64 = AtomicU64::new(0);
const HOST: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/owned_data/owned_leaf_vec/host.js"
);
const DECLARATION: &str = r#"module app.leaf;
@id("app.leaf.row") record Row {
 @id("app.leaf.row.priority") priority:i64,
 @id("app.leaf.row.title") title:string,
 @id("app.leaf.row.payload") payload:Bytes,
}
"#;

fn run_wasm(body: &str, status: u32, value: i64, refusal: &str) {
    run_wasm_status(body, status, value, refusal, None);
}

fn run_wasm_status(body: &str, status: u32, value: i64, refusal: &str, domain: Option<&str>) {
    let source = format!("{DECLARATION}{body}");
    let program = semaprax::check(&source, "owned-leaf-vec-wasm.spx")
        .expect("source and HIR must admit the owned-leaf profile");
    let bytes =
        semaprax::wasm::emit_module(&program).expect("Core Wasm must lower the owned-leaf profile");
    let path = std::env::temp_dir().join(format!(
        "owned-leaf-vec-{}-{}.wasm",
        std::process::id(),
        SEQUENCE.fetch_add(1, Ordering::Relaxed),
    ));
    std::fs::write(&path, bytes).unwrap();
    let mut command = Command::new("node");
    command
        .arg(HOST)
        .arg(&path)
        .arg(status.to_string())
        .arg(value.to_string())
        .arg(refusal);
    if let Some(domain) = domain {
        command.arg(domain);
    }
    let output = command
        .output()
        .expect("Node must execute the private host");
    std::fs::remove_file(path).unwrap();
    assert!(
        output.status.success(),
        "{refusal}: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}

